import threading, sys

def run_with_timeout(f, timeout):
    err = []
    def target():
        try:
            f()
        except BaseException as e:
            err.append(e)

    t = threading.Thread(target=target, daemon=True)
    t.start()
    t.join(timeout)
    if t.is_alive():
        return False
    if err:
        raise err[0]
    return True

print('ok')
"

